function triangleKind(sides: number[]): string {
  const [a, b, c] = [...sides].sort((x, y) => x - y);
  if (a + b <= c) return "none";
  const distinct = new Set(sides).size;
  return distinct === 1 ? "equilateral" : distinct === 2 ? "isosceles" : "scalene";
}

